                  g1(17) = g1(17) + v(66, cur)
                  g1(18) = g1(18) + v(67, cur)
                  g1(19) = g1(19) + v(68, cur)
                  g1(20) = g1(20) + v(69, cur)
                  g1(21) = g1(21) + v(70, cur)
                  g1(22) = g1(22) + v(71, cur)
                  g1(23) = g1(23) + v(72, cur)
                  g1(24) = g1(24) + v(73, cur)
