            v(20,1) = qcy*v(5,1) + wqy*v(5,0)
            v(22,1) = qcy*v(6,1) + wqy*v(6,0)
            v(23,1) = qcy*v(7,1) + wqy*v(7,0) &
               + 2.0_dp*oo2ze*v(3,0)
            v(24,1) = paz*v(18,1) + wpz*v(18,0)
            v(25,1) = qcy*v(9,1) + wqy*v(9,0)
            v(36,1) = qcy*v(18,1) + wqy*v(18,0) &
               + 1.0_dp*oo2e*(v(3,1) - re*v(3,0)) &
