            v(15,1) = paz*v(12,1) + wpz*v(12,0)
            v(26,1) = qcy*v(10,1) + wqy*v(10,0)
            v(27,1) = pax*v(23,1) + wpx*v(23,0)
            v(28,1) = pax*v(24,1) + wpx*v(24,0)
            v(29,1) = qcy*v(12,1) + wqy*v(12,0) &
